		// This does not change the layout, it only fixes indices.
		auto A_rq = A
			^ noarr::fix<'r'>(r_idx)
			^ noarr::fix<'q'>(q_idx);

		// ------------------------------------------------------------------
		// Step 1: sum[p] = 0  for all p (for this particular (r,q))
		// ------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// ------------------------------------------------------------------
		// Step 2: sum[p] += A[r][q][s] * C4[s][p]
		//
		// We traverse C4 with 's' as an explicit loop dimension and
		// 'p' as the innermost dimension:
		//
		//   for s
		//     a_rqs = A[r][q][s];
		//     for p
		//       sum[p] += a_rqs * C4[s][p];
		//
		// This keeps accesses to C4 and sum contiguous in memory
		// (both are laid out with 'p' as the fastest dimension),
		// and each A[r][q][s] is loaded exactly once.
		// ------------------------------------------------------------------
		traverser(C4).template for_dims<'s'>([&](auto trav_s) {
			// trav_s has 's' fixed, 'p' is free
			auto state_s = trav_s.state();
			auto s_idx = get_index<'s'>(state_s);

			// Load A[r][q][s] once into a register
			const num_t a_rqs = A_rq[noarr::idx<'p'>(s_idx)];

