			});
		});

		// ------------------------------------------------------------------
		// Step 3: A[r][q][p] = sum[p]
		//
		// We traverse sum and the 1D view A_rq together so that the
		// state only contains 'p' and we write the accumulated values
		// back to A[r][q][p].
		// ------------------------------------------------------------------
		traverser(sum, A_rq).for_each([&](auto state_p) {
			A_rq[state_p] = sum[state_p];
		});
	});
