//
// Original scalar C kernel:
//
// for (r)
//   for (q) {
//     for (p) {
//       sum[p] = 0;
//       for (s)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
