		// 3) Write back:
		//      A[r][q][p] = sum[p]
		//
		//    trav_rq.for_dims<'p'> iterates all p for current (r, q).
		//    The state_rqp it produces has ('r', 'q', 'p'); when indexing
		//    sum, the extra 'r' and 'q' indices are simply ignored.
		// ------------------------------------------------------------------
