//       }
//       for (p)
//         A[r][q][p] = sum[p];
//     }
//
// Optimized Noarr version keeps the same mathematical
// computation and per‑p accumulation order over s, but
// reorganizes loops to improve locality:
//
//   for (r)
//     for (q) {
//       for (p) sum[p] = 0;
//       for (s) {
//         a = A[r][q][s];
//         for (p) sum[p] += a * C4[s][p];
//       }
//       for (p) A[r][q][p] = sum[p];
//     }
//
// This ordering
//   - walks A[r][q][s] linearly in s,
//   - walks C4[s][p] row‑wise in p (contiguous),
//   - walks sum[p] contiguously in all inner loops,
// and avoids rebuilding per‑p views of C4 and repeatedly
// recomputing A[r][q][s] inside the innermost loop.
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

#pragma scop
	// Pre-create traversers that we will reuse inside the kernel.
	//  - trav_A_sum drives the outer (r,q) loops.
	//  - trav_C4 drives (s,p) loops over the fixed matrix C4.
	//  - trav_sum drives loops over the 1D temporary buffer sum[p].
	auto trav_A_sum = traverser(A, sum);
	auto trav_C4    = traverser(C4);
	auto trav_sum   = traverser(sum);

	// Outer loops over r and q (same as original kernel)
	trav_A_sum.template for_dims<'r', 'q'>([&](auto trav_rq) {
		// trav_rq has dimensions: r, q fixed; p remaining.
		// Extract the current (r,q) once and reuse them.
		auto rq_state = trav_rq.state();
		auto r_idx = get_index<'r'>(rq_state);
		auto q_idx = get_index<'q'>(rq_state);

		// ------------------------------------------------------------------
		// 1) Initialize sum[p] = 0 for this (r,q)
		// ------------------------------------------------------------------
		// We use trav_sum, which iterates the 1D 'p' dimension linearly.
		trav_sum.for_each([&](auto state_p) {
			// state_p only carries 'p'; A and C4 ignore it, sum uses it.
			sum[state_p] = static_cast<num_t>(0);
		});

		// ------------------------------------------------------------------
		// 2) Accumulate sum[p] = Σ_s A[r][q][s] * C4[s][p]
		// ------------------------------------------------------------------
		//
		// We iterate s outermost (trav_C4.for_dims<'s'>) and for each s:
		//   - load A[r][q][s] once and keep it in a_rqs,
		//   - iterate p as the innermost loop (trav_s.for_each) accessing
		//     C4[s][p] and sum[p] contiguously.
		//
		// For each fixed p, the sequence of updates to sum[p] still follows
		// s = 0,1,2,...,NP-1 (only interleaved with updates to other sum[*]),
		// so the floating-point accumulation order per element is preserved.
		trav_C4.template for_dims<'s'>([&](auto trav_s) {
			// trav_s has dimension 's' fixed; 'p' remains.
			auto s_state = trav_s.state();
			auto s_idx   = get_index<'s'>(s_state);

			// Load A[r][q][s] once for this (r,q,s); it's reused for all p.
			auto state_rqs = idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx);
			num_t a_rqs = A[state_rqs];

			// Now iterate p contiguously within this row s of C4.
			trav_s.for_each([&](auto state_sp) {
				// state_sp carries 's' and 'p':
				//   - C4[state_sp] == C4[s][p]
				//   - sum[state_sp] == sum[p] (sum ignores 's')
				sum[state_sp] += a_rqs * C4[state_sp];
			});
		});

		// ------------------------------------------------------------------
		// 3) Write back: A[r][q][p] = sum[p]
		// ------------------------------------------------------------------
		// trav_rq.for_each iterates all p for the current (r,q); the state
		// has {r,q,p}, but sum ignores r,q and only uses p.
		trav_rq.for_each([&](auto state_rqp) {
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

	auto C4 = noarr::make_bag(
		noarr::scalar<num_t>()
		^ C4_layout
		^ noarr::set_length<'s'>(np)
		^ noarr::set_length<'p'>(np));

	auto sum = noarr::make_bag(
		noarr::scalar<num_t>()
		^ sum_layout
		^ noarr::set_length<'p'>(np));

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print output (to prevent DCE and to check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'r' for a more natural outer dimension in the dump
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
